                (List<Map<String, Object>>) fixture.get("projectTags");
        if (projectTags != null) {
            for (Map<String, Object> link : projectTags) {
                // The join row's own id is IDENTITY-generated; the fixture names only the pair.
                jdbc.update("INSERT INTO project_tags (project_id, tag_id) VALUES (?, ?)",
                        ((Number) link.get("projectId")).longValue(),
                        ((Number) link.get("tagId")).longValue());
            }
        }
        List<Map<String, Object>> invoices = (List<Map<String, Object>>) fixture.get("invoices");
        if (invoices != null) {
            for (Map<String, Object> invoice : invoices) {
                // status is optional in a fixture; default to UNPAID (matching Flyway V5) when absent.
                Object status = invoice.get("status");
                // issuedDate/dueDate are optional; fall back to the Flyway V7 column defaults when absent.
                Object issuedDate = invoice.get("issuedDate");
                Object dueDate = invoice.get("dueDate");
                // An invoice is built from line items (Flyway V13). Its amount is the worked-out sum
                // of qty * unitPrice across them (zero when there are none yet) — a fixture no longer
                // types a figure, it lists what is charged. (An explicit `amount` still wins if a
                // fixture gives one, for back-compatibility with lump-sum invoices.)
                List<Map<String, Object>> lineItems =
                        (List<Map<String, Object>>) invoice.get("lineItems");
                java.math.BigDecimal amount = java.math.BigDecimal.ZERO;
                if (lineItems != null) {
                    for (Map<String, Object> line : lineItems) {
                        java.math.BigDecimal unitPrice =
                                new java.math.BigDecimal(line.get("unitPrice").toString());
                        int qty = ((Number) line.get("qty")).intValue();
                        amount = amount.add(unitPrice.multiply(java.math.BigDecimal.valueOf(qty)));
                    }
                }
                if (invoice.get("amount") != null) {
                    amount = new java.math.BigDecimal(invoice.get("amount").toString());
                }
                long invoiceId = ((Number) invoice.get("id")).longValue();
                jdbc.update("INSERT INTO invoices (id, project_id, amount, status, issued_date, due_date)"
                        + " VALUES (?, ?, ?, ?, COALESCE(?, CURRENT_DATE),"
                        + " COALESCE(?, DATEADD('DAY', 30, CURRENT_DATE)))",
                        invoiceId,
                        ((Number) invoice.get("projectId")).longValue(),
                        amount,
                        status != null ? status.toString() : "UNPAID",
                        issuedDate != null ? java.sql.Date.valueOf(issuedDate.toString()) : null,
                        dueDate != null ? java.sql.Date.valueOf(dueDate.toString()) : null);
                if (lineItems != null) {
                    for (Map<String, Object> line : lineItems) {
                        jdbc.update("INSERT INTO invoice_line_items"
                                + " (id, invoice_id, description, qty, unit_price) VALUES (?, ?, ?, ?, ?)",
                                ((Number) line.get("id")).longValue(), invoiceId,
                                line.get("description"), ((Number) line.get("qty")).intValue(),
                                new java.math.BigDecimal(line.get("unitPrice").toString()));
                    }
                }
            }
        }
        List<Map<String, Object>> payments = (List<Map<String, Object>>) fixture.get("payments");
        if (payments != null) {
            long maxId = 0;
            for (Map<String, Object> payment : payments) {
                long id = ((Number) payment.get("id")).longValue();
                maxId = Math.max(maxId, id);
                // Explicit fixture id (JPA save() would ignore it on an IDENTITY column).
                jdbc.update("INSERT INTO payments (id, invoice_id, amount, paid_date)"
                        + " VALUES (?, ?, ?, ?)",
                        id,
                        ((Number) payment.get("invoiceId")).longValue(),
                        new java.math.BigDecimal(payment.get("amount").toString()),
                        java.sql.Date.valueOf(payment.get("date").toString()));
            }
            // Explicit-id inserts don't advance H2's IDENTITY counter, so a later JPA save() would
            // regenerate a seeded id and collide. Restart the counter past the seeded ids.
            if (maxId > 0) {
                jdbc.execute("ALTER TABLE payments ALTER COLUMN id RESTART WITH " + (maxId + 1));
            }
        }
    }
}

import { useSearchParam, asFlag } from '../../url/useSearchParam';
import { formatMoney } from '../../ui/money';
import { useClientStatement } from './statement';

// A client's statement: all of their invoices gathered in one place, each with what is still due,
// and the total they still owe. Whether the statement is open lives in the URL (`statement` key,
// CLAUDE.md rule 4), so it outlives the click and is shareable; the open control owns that key.
export function ClientStatement({ clientId }: { clientId: number }) {
  const [open, setOpen] = useSearchParam('statement', asFlag);
  const { data } = useClientStatement(clientId);

  if (!open) {
    return (
      <button type="button" data-testid="client-statement-open" onClick={() => setOpen(true)}>
        Statement
      </button>
    );
  }

  if (!data) {
    return null;
  }

  return (
    <section data-testid="client-statement">
      <table data-testid="client-statement-table">
        <thead>
          <tr>
            <th>Invoice</th>
            <th>Amount</th>
            <th>Paid</th>
            <th>Due</th>
            <th>Status</th>
          </tr>
        </thead>
        <tbody>
          {data.invoices.map((invoice) => (
            <tr key={invoice.id} data-testid={`statement-invoice-row-${invoice.id}`}>
              <td data-testid="statement-invoice-id">{invoice.id}</td>
              <td data-testid="statement-invoice-amount">{formatMoney(invoice.amount)}</td>
              <td data-testid="statement-invoice-paid">{formatMoney(invoice.paid)}</td>
              <td data-testid="statement-invoice-due">{formatMoney(invoice.due)}</td>
              <td data-testid="statement-invoice-status">{invoice.status}</td>
            </tr>
          ))}
        </tbody>
      </table>
      <p>
        Total owed:{' '}
        <strong data-testid="client-outstanding-total">
          {formatMoney(data.outstandingTotal)}
        </strong>
      </p>
    </section>
  );
}

import { Link } from '@tanstack/react-router';
import { InvoiceListToolbar } from '../../slots/defs/invoiceListToolbar';
import { InvoiceRow } from '../../slots/defs/invoiceRow';
import { useSearchParam, asString } from '../../url/useSearchParam';
import { formatMoney } from '../../ui/money';
import { useInvoices, useSendInvoice } from './invoices';

// A project's invoices and what they add up to. Reads its own query key (scoped to the project) and
// derives the total from the rows — the aggregate is never stored, so it always matches the list.
// Each row shows its status, which is WORKED OUT from the payments recorded against the invoice
// (SENT while unpaid, PARTIAL once part paid, PAID once covered), and the control for its next step:
// Send while DRAFT, then Open to record payments — there is no mark-paid-by-hand flip anymore. The
// ordering comes from the shared `invoiceSort` URL key (set by a toolbar control), so the server
// returns the rows already in order.
export function InvoiceList({ projectId }: { projectId: number }) {
  const [sort] = useSearchParam('invoiceSort', asString);
  const { data: invoices } = useInvoices(projectId, sort || undefined);
  const send = useSendInvoice(projectId);

  if (!invoices) {
    return null;
  }

  const total = invoices.reduce((sum, invoice) => sum + Number(invoice.amount), 0);

  return (
    <>
    <InvoiceListToolbar.Slot projectId={projectId} />
    <table data-testid="project-invoices-table">
      <thead>
        <tr>
          <th>Amount</th>
          <th>Issued</th>
          <th>Due</th>
          <th>Left to pay</th>
          <th>Status</th>
          <th></th>
        </tr>
      </thead>
      <tbody>
        {invoices.map((invoice) => (
          <tr key={invoice.id} data-testid={`invoice-row-${invoice.id}`}>
            <td data-testid="invoice-amount">{formatMoney(invoice.amount)}</td>
            <td data-testid="invoice-issued">{invoice.issuedDate}</td>
            <td data-testid="invoice-due">{invoice.dueDate}</td>
            <td>
              <InvoiceRow.Slot invoice={invoice} />
            </td>
            <td data-testid="invoice-status">{invoice.status}</td>
            <td>
              <Link
                to="/invoices/$invoiceId"
                params={{ invoiceId: String(invoice.id) }}
                data-testid={`invoice-open-${invoice.id}`}
              >
                Open
              </Link>
              {invoice.status === 'DRAFT' && (
                <button
                  type="button"
                  data-testid={`invoice-send-${invoice.id}`}
                  disabled={send.isPending}
                  onClick={() => send.mutate({ id: invoice.id })}
                >
                  Send
                </button>
              )}
            </td>
          </tr>
        ))}
      </tbody>
      <tfoot>
        <tr>
          <td data-testid="project-invoices-total">{formatMoney(total)}</td>
        </tr>
      </tfoot>
    </table>
    </>
  );
}

